class AccessibilityState extends ChangeNotifier {
  bool highContrast = false, screenReaderSupport = true; double fontSizeScale = 1.0;
  void setContrast(bool value) { highContrast=value; notifyListeners(); }
  void setReaderSupport(bool value) { screenReaderSupport=value; notifyListeners(); }
  void setFontScale(double value) { fontSizeScale=value; notifyListeners(); }
}
final accessibility = AccessibilityState();

class UbsApp extends StatelessWidget { const UbsApp({super.key});
  @override Widget build(BuildContext context) => AnimatedBuilder(animation: accessibility, builder: (_, __) {
